import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { z } from "zod";
import { SessionAccessModeSchema } from "../../shared/state/index.js";
import { LIBRETTO_CONFIG_PATH } from "./context.js";
const CURRENT_CONFIG_VERSION = 1;
const ViewportConfigSchema = z.object({
  width: z.number().int().min(1),
  height: z.number().int().min(1)
});
const WindowPositionConfigSchema = z.object({
  x: z.number().int(),
  y: z.number().int()
});
const LibrettoConfigSchema = z.object({
  version: z.literal(CURRENT_CONFIG_VERSION),
  snapshotModel: z.string().min(1).optional(),
  viewport: ViewportConfigSchema.optional(),
  windowPosition: WindowPositionConfigSchema.optional(),
  provider: z.string().optional(),
  sessionMode: SessionAccessModeSchema.optional(),
  experiments: z.record(z.string(), z.boolean()).optional()
}).passthrough();
function formatConfigIssues(error) {
  return error.issues.map((issue) => `  - ${issue.path.join(".") || "root"}: ${issue.message}`).join("\n");
}
function formatExpectedConfigExample() {
  return JSON.stringify(
    {
      version: CURRENT_CONFIG_VERSION,
      viewport: {
        width: 1280,
        height: 800
      },
      windowPosition: {
        x: 1600,
        y: 120
      },
      sessionMode: "write-access"
    },
    null,
    2
  );
}
function invalidConfigError(configPath, detail) {
  return new Error(
    [
      `Config is invalid at ${configPath}.`,
      detail ? `Problems:
${detail}` : null,
      "Expected config example:",
      formatExpectedConfigExample(),
      "Notes:",
      '  - "viewport", "windowPosition", and "sessionMode" are optional.',
      '  - "snapshotModel" is deprecated and ignored by snapshot.',
      "Fix the file to match this shape, or delete it and rerun setup."
    ].filter(Boolean).join("\n")
  );
}
function parseConfig(raw, configPath) {
  let parsedJson;
  try {
    parsedJson = JSON.parse(raw);
  } catch (error) {
    throw invalidConfigError(
      configPath,
      `  - root: Invalid JSON: ${error instanceof Error ? error.message : String(error)}`
    );
  }
  const parsed = LibrettoConfigSchema.safeParse(parsedJson);
  if (!parsed.success) {
    throw invalidConfigError(configPath, formatConfigIssues(parsed.error));
  }
  return parsed.data;
}
function readLibrettoConfig(configPath = LIBRETTO_CONFIG_PATH) {
  if (!existsSync(configPath)) {
    return { version: CURRENT_CONFIG_VERSION };
  }
  return parseConfig(readFileSync(configPath, "utf-8"), configPath);
}
function writeLibrettoConfig(config, configPath = LIBRETTO_CONFIG_PATH) {
  const parsed = LibrettoConfigSchema.parse(config);
  mkdirSync(dirname(configPath), { recursive: true });
  writeFileSync(configPath, JSON.stringify(parsed, null, 2), "utf-8");
  return parsed;
}
function readSnapshotModel(configPath = LIBRETTO_CONFIG_PATH) {
  return readLibrettoConfig(configPath).snapshotModel ?? null;
}
function writeSnapshotModel(model, configPath = LIBRETTO_CONFIG_PATH) {
  let librettoConfig;
  try {
    librettoConfig = readLibrettoConfig(configPath);
  } catch {
    librettoConfig = { version: CURRENT_CONFIG_VERSION };
  }
  writeLibrettoConfig(
    {
      ...librettoConfig,
      version: CURRENT_CONFIG_VERSION,
      snapshotModel: model
    },
    configPath
  );
  return model;
}
function clearSnapshotModel(configPath = LIBRETTO_CONFIG_PATH) {
  const librettoConfig = readLibrettoConfig(configPath);
  if (!librettoConfig.snapshotModel) return false;
  const { snapshotModel: _, ...rest } = librettoConfig;
  writeLibrettoConfig(
    {
      ...rest
    },
    configPath
  );
  return true;
}
export {
  CURRENT_CONFIG_VERSION,
  LibrettoConfigSchema,
  ViewportConfigSchema,
  WindowPositionConfigSchema,
  clearSnapshotModel,
  readLibrettoConfig,
  readSnapshotModel,
  writeLibrettoConfig,
  writeSnapshotModel
};
